typedef long long ll;

static int cmp_ll(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N, K;
    ll L, U, V, T;

    if (scanf("%d %lld %lld %lld %lld %d", &N, &L, &U, &V, &T, &K) != 6) {
        return 0;
    }

    ll *x = (ll *)malloc((N + 2) * sizeof(ll));
    for (int i = 1; i <= N; i++) scanf("%lld", &x[i]);

    x[0] = 0;
    x[N + 1] = L;
    qsort(x + 1, N, sizeof(ll), cmp_ll);

    /*
      DP idea:
      Let dp[i][j] = minimum time to reach position x[i], with j carrots in hand,
      and currently NOT under acceleration effect.
      From such a state, before moving on we may pick carrot at x[i] if it exists.

      If we eat a carrot at position x[i], then for the next T seconds speed is V.
      During this boosted interval, we may pass several carrot positions and collect them
      (up to capacity K), but cannot refresh boost unless we choose to stop exactly at some
      carrot position and eat there. Since eating/collecting is instant and positions are discrete,
      transitions only need to consider ending the current boost at:
        - some carrot position within distance V*T from x[i], where we may eat again
        - or any later point after boost expires; but after expiry, optimal is to continue
          until the next relevant position (goal or next carrot), which is represented by
          reaching some x[m] without boost.

      We model one "segment" from x[i] in two ways:
        1) Run normally to x[i+1] / later positions without boost:
           from non-boost state, just normal running.
        2) If have carrot available after collecting at x[i], eat one and move.

      Simpler equivalent DP:
      States only at special positions x[i].
      From x[i] with j carrots before optional pickup:
        - pickup if i in [1..N]: j' = min(K, j+1), else j'=j
        - move normally to x[m] (m>i): time += (x[m]-x[i])/U, carrots unchanged
        - if j'>0, eat one:
            during first min(dist, V*T) meters speed V, remainder speed U
            while passing carrot positions between i and m, we can collect them, capped by K
            final carrots = min(K, j'-1 + (#carrots passed in (i,m])))

      O(N^2 K), enough for moderate constraints.
      Since statement image omitted constraints, use double DP.
    */

    const double INF = 1e100;
    double **dp = (double **)malloc((N + 2) * sizeof(double *));
    for (int i = 0; i <= N + 1; i++) {
        dp[i] = (double *)malloc((K + 1) * sizeof(double));
        for (int j = 0; j <= K; j++) dp[i][j] = INF;
    }

    dp[0][0] = 0.0;

    for (int i = 0; i <= N; i++) {
        for (int j = 0; j <= K; j++) {
            if (dp[i][j] >= INF / 2) continue;

            int have = j;
            if (i >= 1 && i <= N && have < K) have++;  // pick carrot at current position

            for (int m = i + 1; m <= N + 1; m++) {
                ll dist = x[m] - x[i];

                // Move without eating
                int cnt = m - i - 1; // carrots passed strictly between i and m
                int nj = have + cnt;
                if (nj > K) nj = K;
                double t1 = dp[i][j] + (double)dist / (double)U;
                if (t1 < dp[m][nj]) dp[m][nj] = t1;

                // Move after eating one carrot
                if (have > 0) {
                    ll fastDist = V * T;
                    double t2;
                    if (dist <= fastDist) {
                        t2 = dp[i][j] + (double)dist / (double)V;
                    } else {
                        t2 = dp[i][j] + (double)T + (double)(dist - fastDist) / (double)U;
                    }
                    nj = (have - 1) + cnt;
                    if (nj > K) nj = K;
                    if (t2 < dp[m][nj]) dp[m][nj] = t2;
                }
            }
        }
    }

    double ans = INF;
    for (int j = 0; j <= K; j++) {
        if (dp[N + 1][j] < ans) ans = dp[N + 1][j];
    }

    printf("%.10f\n", ans);

    for (int i = 0; i <= N + 1; i++) free(dp[i]);
    free(dp);
    free(x);
    return 0;
}

