import java.io.*;
import java.util.*;

/*
We model positions on a line:
0 = start, L = goal, and N carrot positions in between.

State:
dp[i][j] = minimum time to arrive exactly at position i while holding j carrots,
           and with NO active speed boost at that moment.

Why "no active boost" only?
If a boost is active after eating a carrot, during the next T seconds the rabbit runs at speed V.
Since carrots can be picked/eaten instantly at carrot positions only, once we choose to eat before
moving from one position to another, the whole next segment is run either:
- fully under boost, if segment length <= V*T
- partly under boost then normal speed, otherwise

After finishing a segment, if boost time remains and there are no carrots in between, continuing
through later segments without decision points is equivalent to directly jumping to the farthest
position reachable within V*T. Thus transitions can be handled by "eat one carrot now and jump
forward to any later position", with travel time determined by segment length.

Transitions from position i with j carrots:
1) Do not eat:
   move to next position i+1 at normal speed.
   If i+1 is a carrot, carrots increase by 1 (capped by K).
2) Eat one carrot if j>0:
   For any later position p>i:
     dist = x[p]-x[i]
     time = min(dist/V, T + (dist - V*T)/U if dist>V*T)
   Arrive at p with no active boost.
   If p is a carrot, carrots increase by 1 (capped by K).

This is O(N^2*K), fine for moderate constraints typical for this problem.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int K = fs.nextInt();
        long L = fs.nextLong();
        double U = fs.nextLong();
        double V = fs.nextLong();
        double T = fs.nextLong();

        long[] carrots = new long[N];
        for (int i = 0; i < N; i++) carrots[i] = fs.nextLong();
        Arrays.sort(carrots);

        // positions: 0=start, 1..N=carrots, N+1=goal
        long[] x = new long[N + 2];
        x[0] = 0;
        for (int i = 0; i < N; i++) x[i + 1] = carrots[i];
        x[N + 1] = L;

        double INF = 1e100;
        double[][] dp = new double[N + 2][K + 1];
        for (int i = 0; i < N + 2; i++) Arrays.fill(dp[i], INF);
        dp[0][0] = 0.0;

        double boostedReach = V * T;

        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= K; j++) {
                double cur = dp[i][j];
                if (cur >= INF / 2) continue;

                // Option 1: move normally to next position
                int ni = i + 1;
                double dist1 = x[ni] - x[i];
                int nj = j + (ni <= N ? 1 : 0);
                if (nj > K) nj = K;
                dp[ni][nj] = Math.min(dp[ni][nj], cur + dist1 / U);

                // Option 2: eat one carrot now, then move to any later position
                if (j > 0) {
                    for (int p = i + 1; p <= N + 1; p++) {
                        double dist = x[p] - x[i];
                        double time;
                        if (dist <= boostedReach) {
                            time = dist / V;
                        } else {
                            time = T + (dist - boostedReach) / U;
                        }
                        int cj = j - 1 + (p <= N ? 1 : 0);
                        if (cj > K) cj = K;
                        dp[p][cj] = Math.min(dp[p][cj], cur + time);
                    }
                }
            }
        }

        double ans = INF;
        for (int j = 0; j <= K; j++) ans = Math.min(ans, dp[N + 1][j]);

        System.out.printf(Locale.US, "%.10f%n", ans);
    }
}

