    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long L = Long.parseLong(st.nextToken()); // distance to goal
        int N = Integer.parseInt(st.nextToken()); // number of carrots
        long U = Long.parseLong(st.nextToken()); // normal speed
        long V = Long.parseLong(st.nextToken()); // boosted speed
        long T = Long.parseLong(st.nextToken()); // boost duration
        int K = Integer.parseInt(st.nextToken()); // max carrots held

        long[] positions = new long[N];
        for (int i = 0; i < N; i++) {
            positions[i] = Long.parseLong(br.readLine());
        }

        // dp[i][j] = maximum distance covered by time t (or min time for distance)
        // We'll use DP over carrots: dp[j] = min time to reach position of carrot i
        // with j carrots currently in hand (0..K) after picking up this carrot.
        // We process carrots in order, and also consider the final segment to goal.

        final double INF = Double.MAX_VALUE;
        double[][] dp = new double[N + 1][K + 1];
        for (int i = 0; i <= N; i++) Arrays.fill(dp[i], INF);
        dp[0][0] = 0; // before any carrot, at position 0, 0 carrots held

        long prevPos = 0;
        for (int i = 0; i < N; i++) {
            long curPos = positions[i];
            double segmentLen = curPos - prevPos;
            // Before picking up this carrot, we may have any j (0..K) carrots.
            for (int j = 0; j <= K; j++) {
                if (dp[i][j] == INF) continue;
                double curTime = dp[i][j];
                // We travel from prevPos to curPos with current state (j carrots held, and possibly boost active)
                // But boost state depends on time since last carrot eaten.
                // We need to know if we are currently boosted.
                // Instead, we simulate the segment considering that we might have a boost active from previous carrot.
                // We'll compute the earliest time to reach curPos with j carrots held (not counting this one yet).
                // Then we decide whether to pick this carrot (increase held count) or not.

                // But boost duration T is counted from last carrot eaten. If we have j carrots held, the last carrot eaten
                // was at some time. We don't track that time directly. So we need to track the time when boost expires.
                // Let's reframe: we can think of the state as (i, j, boostEndTime) but that's too large.
                // Alternative: Use DP over positions with time as continuous, but we can treat boost as:
                // When you eat a carrot, you get a boost for T seconds. During that boost, speed = V.
                // After T seconds, speed = U until next carrot.
                // So the speed profile is piecewise constant.
                // We can compute time for a segment given whether we start with boost active and how much boost time remains.
